/* timing.h: the trace-driven timing model of sim64 (--timing).  See docs/timing-model.md.
 *
 * Two halves.  The executor (build/pdp64exec_tm.c, generated by tools/mk-exec-tm.py from the shared pdp64exec.c) logs, for the instruction being
 * run, the registers it reads and writes in order, its class, and (sim64.c) its memory accesses: struct tm_rec.  common/timing.c consumes the
 * record of each executed instruction in program order and advances any number of independent model instances (tm_feed), each with its own
 * parameters.  The model never changes what the program does.
 */
#ifndef PDP64_TIMING_H
#define PDP64_TIMING_H
#include <stdint.h>
#include <stdio.h>
#include "pdp64enc.h"
struct fmt;

/* ---- the log of one instruction -------------------------------------------------------------------------------------- */
enum { TM_EV_R, TM_EV_W, TM_EV_M, TM_EV_WA, TM_EV_MA, TM_EV_LD, TM_EV_ST };	/* read, write, read-modify-write, address-update write (base register of an addressing mode, sp), the same read-modify-write, load, store */
enum { TM_REG_FN = 32, TM_REG_FZ = 32, TM_REG_FV = 32, TM_REG_FC = 32, TM_REG_DP = 33, TM_NREG = 34 };	/* the four flags are one resource (register 32), DP is 33 */
#define TM_MAXEV 160

struct tm_ev { uint8_t k, r, sz; uint64_t addr; };	/* r: the register for R W M WA MA; sz, addr: LD ST */

enum { TC_ALU, TC_MOVE, TC_MUL, TC_DIV, TC_FADD, TC_FMUL, TC_FDIV, TC_BLOCK, TC_BRANCH, TC_CALL, TC_RET, TC_SYS, TC_NCLASS };
enum { BK_NONE, BK_COND, BK_JMP_D, BK_JMP_I, BK_CALL_D, BK_CALL_I, BK_RET };	/* kind of control transfer */

struct tm_rec {
	uint64_t pc, next;		/* address; the pc after the instruction ran */
	int len;			/* bytes */
	uint8_t cls, bk, back;		/* TC_*; BK_*; a conditional branch whose displacement is negative */
	uint8_t fused;			/* a fused instruction (movcall popmret popret mov2) */
	int n;				/* events logged (stops at TM_MAXEV; the masks and counts below do not) */
	struct tm_ev ev[TM_MAXEV];
	uint64_t rmask, wmask;		/* bit r: register r (32: flags, 33: dp) read / written */
	unsigned nld, nst, ldb, stb;	/* number and bytes of memory accesses */
};
extern struct tm_rec tm_cur;
extern int tm_on;

static inline void tm_ev(int k, int r)
{
	if (!tm_on) return;
	struct tm_rec *t = &tm_cur;
	if (k == TM_EV_R || k == TM_EV_M || k == TM_EV_MA) t->rmask |= 1ull << r;
	if (k != TM_EV_R) t->wmask |= 1ull << r;
	if (t->n < TM_MAXEV) {
		if (r == TM_REG_FN && t->n && t->ev[t->n - 1].r == r && t->ev[t->n - 1].k == k) return;	/* the flags are written in several steps */
		struct tm_ev *e = &t->ev[t->n++];
		e->k = k; e->r = r;
	}
}
static inline uint64_t tm_rd(const uint64_t *a, int i) { tm_ev(TM_EV_R, i); return a[i]; }
static inline uint64_t *tm_wr(uint64_t *a, int i, int kind)
{
	if (kind == TM_EV_M || kind == TM_EV_MA) { tm_ev(TM_EV_R, i); tm_ev(kind == TM_EV_M ? TM_EV_W : TM_EV_WA, i); }
	else tm_ev(kind, i);
	return &a[i];
}
static inline void tm_set(uint64_t *a, int i, uint64_t v, int kind) { tm_ev(kind, i); a[i] = v; }
void tm_mem(int store, uint64_t addr, int size);	/* from the host's load and store hooks */
void tm_fmt(const struct fmt *f);			/* the decoded instruction of the original encoding about to run */
void tm_enc(int enc, int mn, const char *name, const struct einsn *in);	/* the same for pdp64/16 and /32 */
void tm_begin(uint64_t pc, int nparcels);		/* an instruction is decoded (the profile hook) */

/* ---- the model ------------------------------------------------------------------------------------------------------- */
struct tm_model;
/* Parse "name=val,name=val,..." into a new model for the encoding enc (0 r20, 1 16, 2 32).  NULL and a message in err on failure.  `tm_help` lists the parameters. */
struct tm_model *tm_new(const char *spec, int enc, char *err, size_t errsz);
void tm_help(FILE *o);
void tm_retire(struct tm_model **m, int nm, uint64_t next_pc);	/* the instruction in tm_cur has completed: feed it to every model */
void tm_set_text(uint64_t lo, uint64_t hi);		/* the range of addresses of the program, for the per-pc profile */
void tm_report(struct tm_model **m, int nm, FILE *o, const char *prog);	/* one `tm ...` line per model, then the descriptions */
void tm_pcprof(struct tm_model *m);		/* collect the per-pc cycles of this model */
void tm_pcdump(struct tm_model *m, FILE *o);
void tm_total_cycles(struct tm_model *m, uint64_t *cycles, uint64_t *insns);
#endif
